import { aesInitCheck, aesParamsCheck, aesMethods } from './utils/aes.mjs'
import { createCipherApi } from './utils/cipher.mjs'

// WebCrypto-based implementation

const { subtle } = globalThis.crypto

function aesSubtleType(mode) {
  if (mode === 'CBC') return 'AES-CBC'
  if (mode === 'CTR') return 'AES-CTR'
  if (mode === 'GCM') return 'AES-GCM'
  throw new Error('Unexpected AES mode')
}

function aesSubtleParams(mode, nonce, additionalData) {
  const name = aesSubtleType(mode)
  if (mode === 'CBC') return { name, iv: nonce }
  if (mode === 'CTR') return { name, counter: nonce, length: 64 }
  if (mode === 'GCM') return { name, iv: nonce, ...(additionalData ? { additionalData } : {}) }
  throw new Error('Unexpected AES mode')
}

export async function aes(mode, key, usage) {
  aesInitCheck(mode, key, usage)
  const subtleUsage = usage ? [usage] : ['encrypt', 'decrypt']
  const subtleKey = await subtle.importKey('raw', key, aesSubtleType(mode), false, subtleUsage)
  key = null // eslint-disable-line no-param-reassign

  return createCipherApi(usage, {
    async encrypt(data, nonce, additionalData) {
      aesParamsCheck(mode, nonce, additionalData)
      const params = aesSubtleParams(mode, nonce, additionalData)
      return new Uint8Array(await subtle.encrypt(params, subtleKey, data))
    },
    async decrypt(data, nonce, additionalData) {
      aesParamsCheck(mode, nonce, additionalData)
      const params = aesSubtleParams(mode, nonce, additionalData)
      return new Uint8Array(await subtle.decrypt(params, subtleKey, data))
    },
  })
}

const { encryptCBC, decryptCBC, encryptCTR, decryptCTR, encryptGCM, decryptGCM } = aesMethods(aes)

export { encryptCBC, decryptCBC, encryptCTR, decryptCTR, encryptGCM, decryptGCM }
